import chess
import json

class Game:
    def __init__(self, fen=None):
        self.board = chess.Board(fen=fen) if fen else chess.Board()
        self.turn = 'white' if self.board.turn else 'black'
        self.pieces = {square: str(self.board.piece_at(square)) for square in chess.SQUARES}
        self.legal_moves = list(self.board.legal_moves)
        self.status = self._get_status()
        self.winner = self._get_winner()

    def move(self, uci):
        try:
            self.board.push(chess.Move.from_uci(uci))
            self.turn = 'white' if self.board.turn else 'black'
            self.pieces = {square: str(self.board.piece_at(square)) for square in chess.SQUARES}
            self.legal_moves = list(self.board.legal_moves)
            self.status = self._get_status()
            self.winner = self._get_winner()
            return self.state()
        except ValueError as e:
            raise ValueError(str(e))

    def reset(self):
        self.board.reset()
        self.turn = 'white' if self.board.turn else 'black'
        self.pieces = {square: str(self.board.piece_at(square)) for square in chess.SQUARES}
        self.legal_moves = list(self.board.legal_moves)
        self.status = self._get_status()
        self.winner = self._get_winner()
        return self.state()

    def state(self):
        return {
            'fen': str(self.board),
            'turn': self.turn,
            'pieces': self.pieces,
            'legal_moves': [str(move) for move in self.legal_moves],
            'status': self.status,
            'winner': self.winner
        }

    def _get_status(self):
        if self.board.is_checkmate():
            return 'checkmate'
        elif self.board.is_stalemate():
            return 'stalemate'
        elif self.board.is_insufficient_material():
            return 'draw'
        elif self.board.is_repetition():
            return 'draw'
        elif self.board.halfmove_clock >= 100:
            return 'draw'
        elif self.board.fullmove_number >= 50:
            return 'draw'
        elif self.board.is_check():
            return 'check'
        else:
            return 'playing'

    def _get_winner(self):
        if self.board.is_checkmate():
            return 'black' if self.board.turn else 'white'
        elif self.board.is_stalemate():
            return 'draw'
        elif self.board.is_insufficient_material():
            return 'draw'
        elif self.board.is_repetition():
            return 'draw'
        elif self.board.halfmove_clock >= 100:
            return 'draw'
        elif self.board.fullmove_number >= 50:
            return 'draw'
        else:
            return None
